<?php

const MODU = 998244353;
const MAXN = 500;

$fac = array_fill(0, MAXN + 1, 0);
$finv = array_fill(0, MAXN + 1, 0);
$inv = array_fill(0, MAXN + 1, 0);

function initTables() {
    global $fac, $finv, $inv;
    $fac[0] = 1;
    $fac[1] = 1;
    $finv[0] = 1;
    $finv[1] = 1;
    $inv[1] = 1;
    for ($i = 2; $i <= MAXN; $i++) {
        $fac[$i] = $fac[$i - 1] * $i % MODU;
        $inv[$i] = MODU - $inv[MODU % $i] * intdiv(MODU, $i) % MODU;
        $finv[$i] = $finv[$i - 1] * $inv[$i] % MODU;
    }
}

function ModCombination($n, $k) {
    global $fac, $finv;
    if ($n < $k) {
        return 0;
    }
    $ret = 1;
    while ($n > 0 || $k > 0) {
        $ret = $ret * $fac[$n % MODU] % MODU * $finv[$k % MODU] % MODU * $finv[($n - $k) % MODU] % MODU;
        $n = intdiv($n, MODU);
        $k = intdiv($k, MODU);
    }
    return $ret;
}

function Mn($a, $b) {
    if ($a < $b) {
        return $a;
    }
    return $b;
}

$tokens = null;
$tokenIndex = 0;

function ReadToken() {
    global $tokens, $tokenIndex;
    if ($tokens === null) {
        $data = stream_get_contents(STDIN);
        $tokens = preg_split('/\s+/', trim($data), -1, PREG_SPLIT_NO_EMPTY);
        $tokenIndex = 0;
    }
    return $tokens[$tokenIndex++];
}

function ReadString() {
    return ReadToken();
}

function ReadInt() {
    return (int)ReadToken();
}

function solve() {
    $n = ReadInt();
    $x = ReadInt();

    $pow = [];
    for ($i = 0; $i < 501; $i++) {
        $pow[$i] = array_fill(0, 501, 0);
        $pow[$i][0] = 1;
        for ($j = 0; $j < 500; $j++) {
            $pow[$i][$j + 1] = $pow[$i][$j] * $i % MODU;
        }
    }

    $dp = [];
    for ($i = 0; $i < 501; $i++) {
        $dp[$i] = array_fill(0, 501, 0);
    }

    for ($i = 2; $i <= $n; $i++) {
        $jj = Mn($x, $i - 1);
        for ($j = 1; $j <= $jj; $j++) {
            // dp[i][j] = j^i - (j-1)^i
            $dp[$i][$j] = $pow[$j][$i] - $pow[$j - 1][$i];
            $dp[$i][$j] %= MODU;
        }
    }

    for ($i = 2; $i <= $n; $i++) {
        for ($j = 1; $j <= $x; $j++) {
            if ($dp[$i][$j] == 0) {
                continue;
            }
            for ($k = 0; $k <= $n - $i; $k++) {
                $nj = $j + $i + $k - 1;
                if ($nj > $x) {
                    break;
                }
                $dp[$i + $k][$nj] += $dp[$i][$j] * $pow[$i + $k - 1][$k] % MODU * ModCombination($i + $k, $k);
                $dp[$i + $k][$nj] %= MODU;
            }
        }
    }

    $ans = 0;
    for ($j = 1; $j <= $x; $j++) {
        $ans += $dp[$n][$j];
        $ans %= MODU;
    }
    echo ((($ans % MODU) + MODU) % MODU) . "\n";
}

initTables();
solve();
